package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

const (
	proxyAddr    = ":8080"
	backendAddr  = "127.0.0.1:9090"
	shutdownWait = 30 * time.Second
)

var (
	activeConns  int64
	shuttingDown int32
	authSecret   = []byte(os.Getenv("PROXY_AUTH_SECRET"))
)

type ProxyServer struct {
	listener   net.Listener
	connWg     sync.WaitGroup
	shutdownCh chan struct{}
	server     *http.Server
}

func NewProxyServer() *ProxyServer {
	return &ProxyServer{
		shutdownCh: make(chan struct{}),
	}
}

func (ps *ProxyServer) validateAuthToken(provided, expected string) bool {
	// Compare token byte by byte for validation
	if len(provided) != len(expected) {
		return false
	}
	result := byte(0)
	for i := 0; i < len(provided); i++ {
		result |= provided[i] ^ expected[i]
	}
	return result == 0
}

func (ps *ProxyServer) computeExpectedToken(clientID string) string {
	mac := hmac.New(sha256.New, authSecret)
	mac.Write([]byte(clientID))
	return hex.EncodeToString(mac.Sum(nil))
}

func (ps *ProxyServer) authenticateRequest(r *http.Request) bool {
	clientID := r.Header.Get("X-Client-ID")
	token := r.Header.Get("X-Auth-Token")

	if clientID == "" || token == "" {
		return false
	}

	expected := ps.computeExpectedToken(clientID)
	return ps.validateAuthToken(token, expected)
}

func (ps *ProxyServer) handleProxy(w http.ResponseWriter, r *http.Request) {
	if atomic.LoadInt32(&shuttingDown) == 1 {
		http.Error(w, "Service shutting down", http.StatusServiceUnavailable)
		return
	}

	if !ps.authenticateRequest(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	atomic.AddInt64(&activeConns, 1)
	ps.connWg.Add(1)
	defer func() {
		ps.connWg.Done()
		atomic.AddInt64(&activeConns, -1)
	}()

	backendConn, err := net.DialTimeout("tcp", backendAddr, 5*time.Second)
	if err != nil {
		http.Error(w, "Backend unavailable", http.StatusBadGateway)
		return
	}
	defer backendConn.Close()

	reqBody, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		http.Error(w, "Read error", http.StatusBadRequest)
		return
	}

	_, err = backendConn.Write(reqBody)
	if err != nil {
		http.Error(w, "Write error", http.StatusBadGateway)
		return
	}

	respBuf := make([]byte, 4096)
	backendConn.SetReadDeadline(time.Now().Add(10 * time.Second))
	n, err := backendConn.Read(respBuf)
	if err != nil && err != io.EOF {
		http.Error(w, "Backend read error", http.StatusBadGateway)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write(respBuf[:n])
}

func (ps *ProxyServer) drainConnections(ctx context.Context) {
	done := make(chan struct{})
	go func() {
		ps.connWg.Wait()
		close(done)
	}()

	select {
	case <-done:
		fmt.Println("All connections drained")
	case <-ctx.Done():
		fmt.Printf("Drain timeout, %d connections remaining\n", atomic.LoadInt64(&activeConns))
	}
}

func (ps *ProxyServer) Start() error {
	mux := http.NewServeMux()
	mux.HandleFunc("/proxy", ps.handleProxy)
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		if atomic.LoadInt32(&shuttingDown) == 1 {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
		fmt.Fprintf(w, "active_connections: %d", atomic.LoadInt64(&activeConns))
	})

	ps.server = &http.Server{
		Addr:         proxyAddr,
		Handler:      mux,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 15 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-sigCh
		fmt.Println("Shutdown signal received")
		atomic.StoreInt32(&shuttingDown, 1)

		ctx, cancel := context.WithTimeout(context.Background(), shutdownWait)
		defer cancel()

		ps.server.Shutdown(ctx)
		ps.drainConnections(ctx)
		close(ps.shutdownCh)
	}()

	fmt.Printf("Proxy listening on %s\n", proxyAddr)
	if err := ps.server.ListenAndServe(); err != http.ErrServerClosed {
		return err
	}

	<-ps.shutdownCh
	return nil
}

func main() {
	ps := NewProxyServer()
	if err := ps.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
